// ════════════════════════════════════════════════════════════════════
//  เสียงสำหรับคลิป — เส้นที่สอง **แยกจากตัวเล่นสดโดยสิ้นเชิง**
//
//  ★★ ทำไมต้องแยก ไม่ใช้ตัวเล่นเดิม ★★
//   ตัวจองเสียงใน `score_sound_bank.mjs` ผูกกับ **เวลาจริง** (จองล่วงหน้า 2 วิ
//   เติมคิวทุก 250 ms) เพราะมันต้องเล่นให้คนฟังสด · เอามาทำคลิปไม่ได้เลย
//   ที่นี่ใช้ `OfflineAudioContext` ซึ่ง **จองทั้งเพลงทีเดียวได้** และเร็วกว่าเวลาจริง
//   (วัดแล้ว: เชิดจีน 5,693 โหนดใช้ 244 ms · ไม่มีอาการเสียงหายแบบตอนเล่นสด
//    เพราะไม่มีเธรดเรียลไทม์ให้ล้น)
//
//  ★★ และทำไมต้อง **ไม่แตะ** ไฟล์เสียงเดิมเลย ★★
//   นั่นคือส่วนที่เพิ่งแก้บั๊ก "เสียงหายเป็นครั้งคราว" ไปใน 1.0.9 · ของที่ ok แล้ว
//   ห้ามเอามาเสี่ยง · ที่นี่จึงยืมมาแค่ **กฎดนตรี** ผ่าน `sampleFor`/`rateFor`
//   ซึ่งเปิดไว้ให้ด่านตรวจใช้อยู่แล้ว — ไม่มีการคัดลอกกฎมาเขียนซ้ำ
//
//  ★ ภาพกับเสียงตรงกันเพราะ **คิดจากเวลาชุดเดียวกัน** (secPerTick × tick)
//    ไม่ใช่การอัดสดแล้วหวังว่าจะตรง
// ════════════════════════════════════════════════════════════════════
import { marimbaStrike } from '../../packages/engine/marimba.mjs';
import { noteHz } from '../../packages/engine/thai_tuning.mjs';

type Pack = {
  base: string; file: string; count: number; exts: string[];
  synth?: string; sustain?: boolean; releaseMs?: number;
  midi?: number[]; tuning?: string; chingBase?: string;
};
type Bank = {
  sampleFor: (i: number) => { j: number; semis: number };
  rateFor: (i: number, semis: number) => number;
  tuning: () => string;
};
type Song = {
  notes?: Array<{ i: number; t: number; d?: number }>;
  ching?: Array<{ type: number; t: number }>;
  lengthTicks?: number;
};

const SR = 44100;
/** หางเสียงที่ต้องเผื่อไว้ท้ายเพลง — ตัดตรงโน้ตตัวสุดท้ายจะได้เสียง "ห้วน" */
const TAIL = 3.5;

/** โหลดแซมเปิลเข้า context ของคลิป
 *  ★ บัฟเฟอร์ผูกกับ context ที่ถอดรหัสมัน — เอาของตัวเล่นสดมาใช้ไม่ได้ ต้องโหลดใหม่ */
async function loadSamples(ctx: OfflineAudioContext, pack: Pack, system: string) {
  const banks = pack.tuning === 'banks';
  const exts = pack.exts?.length ? pack.exts : ['mp3', 'ogg'];
  const url = (i: number, ext: string) =>
    `${pack.base}${banks ? `/${system}` : ''}/${pack.file}_${String(i).padStart(2, '0')}.${ext}`;
  const jobs: Array<Promise<AudioBuffer | null>> = [];
  for (let i = 1; i <= pack.count; i += 1) {
    jobs.push((async () => {
      for (const ext of exts) {
        try {
          const r = await fetch(url(i, ext));
          if (!r.ok) continue;
          return await ctx.decodeAudioData(await r.arrayBuffer());
        } catch { /* ลองนามสกุลถัดไป */ }
      }
      return null;
    })());
  }
  return Promise.all(jobs);
}

async function loadChing(ctx: OfflineAudioContext, base: string) {
  return Promise.all(['open', 'close'].map(async (n) => {
    for (const ext of ['mp3', 'ogg', 'm4a']) {
      try {
        const r = await fetch(`${base}/${n}.${ext}`);
        if (!r.ok) continue;
        return await ctx.decodeAudioData(await r.arrayBuffer());
      } catch { /* ต่อไป */ }
    }
    return null;
  }));
}

export type ClipAudio = { buffer: AudioBuffer; seconds: number; voices: number };

/**
 * เรนเดอร์เสียงทั้งเพลงเป็นก้อนเดียว
 * @param opts.chingOn  ให้มีฉิ่ง–ฉับ ไหม (ตามสวิตช์บนจอ)
 * @param opts.volume   ความดังตั้งต้นของโน้ต (เท่าตัวเล่นสด)
 */
export async function renderClipAudio(
  song: Song, pack: Pack, bank: Bank, secPerTick: number,
  opts: { chingOn?: boolean; volume?: number } = {},
): Promise<ClipAudio> {
  const notes = (song.notes || []).slice().sort((a, b) => a.t - b.t);
  const chings = opts.chingOn === false ? [] : (song.ching || []).slice().sort((a, b) => a.t - b.t);
  const endTick = Number(song.lengthTicks) || (notes.length ? notes[notes.length - 1].t : 0);
  const seconds = Math.max(1, endTick * secPerTick + TAIL);

  const ctx = new OfflineAudioContext(2, Math.ceil(seconds * SR), SR);
  const system = bank.tuning();

  // ★ บัสสองเส้นเหมือนตัวเล่นสด — เผื่อวันหน้าจะให้ผู้ใช้ตั้งความดังของคลิปแยกได้
  const busInst = ctx.createGain();
  const busChing = ctx.createGain();
  busInst.connect(ctx.destination);
  busChing.connect(ctx.destination);

  const synth = pack.synth || '';
  const [samples, ching] = await Promise.all([
    synth ? Promise.resolve([] as Array<AudioBuffer | null>) : loadSamples(ctx, pack, system),
    chings.length ? loadChing(ctx, pack.chingBase || '/audio/ching') : Promise.resolve([null, null]),
  ]);

  let voices = 0;
  const vol = opts.volume ?? 0.9;

  const strike = (
    buf: AudioBuffer | null, when: number, gain: number,
    durSec: number | null, rate: number, dest: GainNode,
  ) => {
    if (!buf) return;
    const s = ctx.createBufferSource();
    s.buffer = buf;
    if (rate && rate !== 1) s.playbackRate.value = rate;
    const g = ctx.createGain();
    g.gain.value = gain;
    s.connect(g).connect(dest);
    // ★ start ก่อน stop เสมอ — สลับลำดับ Web Audio โยนแล้วเงียบทั้งเพลง (กฎเดียวกับตัวเล่นสด)
    s.start(when);
    if (durSec != null) {
      const rel = Math.max(0.005, (pack.releaseMs || 10) / 1000);
      const off = when + Math.max(0.03, durSec);
      g.gain.setValueAtTime(gain, off);
      g.gain.linearRampToValueAtTime(0.0001, off + rel);
      s.stop(off + rel + 0.01);
    }
    voices += 1;
  };

  // ★★ จองทั้งเพลงทีเดียว — ตรงข้ามกับตัวเล่นสดที่ห้ามทำแบบนี้เด็ดขาด ★★
  //   ออฟไลน์ไม่มีเธรดเสียงเรียลไทม์ให้ล้น จึงเป็นทางที่ถูกที่นี่
  for (const n of notes) {
    const when = n.t * secPerTick;
    const dur = pack.sustain ? (n.d || 0) * secPerTick : null;
    if (synth) {
      const hz = noteHz(pack.midi?.[n.i], system);
      if (hz > 0) { marimbaStrike(ctx, busInst, hz, when, vol, dur, () => {}); voices += 1; }
    } else {
      const { j, semis } = bank.sampleFor(n.i);
      strike(samples[j] ?? null, when, vol, dur, bank.rateFor(n.i, semis), busInst);
    }
  }
  for (const c of chings) {
    // ★ `* 0.5` = สมดุลตั้งต้นระหว่างฉิ่งกับทำนอง — ค่าเดียวกับตัวเล่นสดเป๊ะ
    strike(ching[c.type] || ching[0], c.t * secPerTick, vol * 0.5, null, 1, busChing);
  }

  const buffer = await ctx.startRendering();
  return { buffer, seconds, voices };
}

/** AudioBuffer → ไฟล์ WAV 16 บิต (รูปแบบที่ฝั่ง Rust รับเข้า AVFoundation ได้ตรง)
 *  ★ ไม่บีบ — ไฟล์ใหญ่แต่ไม่เสียคุณภาพ และไม่ต้องพึ่งตัวเข้ารหัสเสียงฝั่งหน้าจอ */
export function wavBytes(buf: AudioBuffer): Uint8Array {
  const ch = Math.min(2, buf.numberOfChannels);
  const n = buf.length;
  const bytes = 44 + n * ch * 2;
  const out = new DataView(new ArrayBuffer(bytes));
  const put = (o: number, s: string) => { for (let i = 0; i < s.length; i += 1) out.setUint8(o + i, s.charCodeAt(i)); };
  put(0, 'RIFF'); out.setUint32(4, bytes - 8, true); put(8, 'WAVE');
  put(12, 'fmt '); out.setUint32(16, 16, true);
  out.setUint16(20, 1, true); out.setUint16(22, ch, true);
  out.setUint32(24, buf.sampleRate, true);
  out.setUint32(28, buf.sampleRate * ch * 2, true);
  out.setUint16(32, ch * 2, true); out.setUint16(34, 16, true);
  put(36, 'data'); out.setUint32(40, n * ch * 2, true);

  const chans: Float32Array[] = [];
  for (let c = 0; c < ch; c += 1) chans.push(buf.getChannelData(c));
  let o = 44;
  for (let i = 0; i < n; i += 1) {
    for (let c = 0; c < ch; c += 1) {
      // ★ ต้องหนีบก่อนแปลง — ค่าที่เกิน ±1 จะวนกลับกลายเป็นเสียงแตกดังปั้ง
      const v = Math.max(-1, Math.min(1, chans[c][i]));
      out.setInt16(o, v < 0 ? v * 0x8000 : v * 0x7fff, true);
      o += 2;
    }
  }
  return new Uint8Array(out.buffer);
}
